"""Moteur de recherche de recettes — projet de fin de chapitre 2."""

RECETTES = [
    {"nom": "carbonara", "ingredients": ["pates", "oeufs", "parmesan", "lardons"], "temps_min": 25, "difficulte": 1},
    {"nom": "omelette", "ingredients": ["oeufs", "beurre"], "temps_min": 10, "difficulte": 1},
    {"nom": "risotto", "ingredients": ["riz", "parmesan", "bouillon", "oignon", "beurre"], "temps_min": 45, "difficulte": 2},
    {"nom": "salade grecque", "ingredients": ["tomates", "concombre", "feta", "olives", "huile"], "temps_min": 15, "difficulte": 1},
    {"nom": "ratatouille", "ingredients": ["aubergine", "courgette", "tomates", "oignon", "huile"], "temps_min": 70, "difficulte": 2},
    {"nom": "pates pesto", "ingredients": ["pates", "basilic", "parmesan", "huile", "ail"], "temps_min": 20, "difficulte": 1},
]

FRIGO = {"oeufs", "parmesan", "pates", "tomates", "huile", "beurre", "ail", "basilic"}


def par_ingredient(recettes, ingredient):
    return [r["nom"] for r in recettes if ingredient in r["ingredients"]]


def realisables(recettes, frigo):
    return [r["nom"] for r in recettes if set(r["ingredients"]) <= frigo]


def trouver(recettes, nom):
    return next((r for r in recettes if r["nom"] == nom), None)


def liste_courses(recettes, nom, frigo):
    recette = trouver(recettes, nom)
    if recette is None:
        return None                     # le CLI traduira en message
    return set(recette["ingredients"]) - frigo


def plus_rapides(recettes, n=3):
    tri = sorted(recettes, key=lambda r: r["temps_min"])
    return [(r["nom"], r["temps_min"]) for r in tri[:n]]


def main():
    print("Commandes : ingredient <nom> | frigo | courses <recette> | rapides | quitter")
    while True:
        mots = input("> ").strip().lower().split(maxsplit=1)

        match mots:
            case ["quitter"]:
                break
            case ["frigo"]:
                noms = realisables(RECETTES, FRIGO)
                print("Réalisables :", ", ".join(noms) if noms else "rien")
            case ["rapides"]:
                for nom, temps in plus_rapides(RECETTES):
                    print(f"- {nom} ({temps} min)")
            case ["ingredient", nom]:
                noms = par_ingredient(RECETTES, nom)
                print(", ".join(noms) if noms else f"aucune recette avec {nom}")
            case ["courses", nom]:
                manquants = liste_courses(RECETTES, nom, FRIGO)
                if manquants is None:
                    print(f"Recette inconnue : {nom}")
                else:
                    print("À acheter :", ", ".join(sorted(manquants)) if manquants else "rien, tout est là")
            case _:
                print("Commande inconnue.")


if __name__ == "__main__":
    main()
```

Vérifications attendues :

- `frigo` → `omelette, pates pesto` (la carbonara bute sur les lardons) ;
- `courses carbonara` → `lardons` ;
- `courses salade grecque` → `concombre, feta, olives` (tri alphabétique pour un affichage stable) ;
- `ingredient parmesan` → `carbonara, risotto, pates pesto`.

Choix de conception à noter : les recettes **restent** des `list` (l'ordre est signifiant), les sets sont construits au moment des opérations ensemblistes ; les fonctions renvoient des données, le CLI s'occupe seul de l'affichage — même séparation métier/présentation qu'au chapitre 1, qui deviendra API/front dans l'app finale.
